export function getTranslation(locale: Locale, key: string): string {
  const workspaceTranslation = WORKSPACE_NAV_TRANSLATIONS[locale]?.[key] || WORKSPACE_NAV_TRANSLATIONS.fr[key];
  if (workspaceTranslation) return workspaceTranslation;
  const dict = DICTIONARIES[locale] || DICTIONARIES.fr;
  return dict[key as keyof Dictionary] || DICTIONARIES.fr[key as keyof Dictionary] || key;
}
